const { Readable, Writable } = require('stream');
const s = (x) => [x instanceof Readable, x instanceof Writable, typeof x.fd, x.fd, !!x.isTTY, typeof x.setEncoding, typeof x.pipe, typeof x.write, x.writable, x.readable].join(' ');
console.log('stdin', s(process.stdin));
console.log('stdout', s(process.stdout));
console.log('stderr', s(process.stderr));
console.log('hwm', process.stdout.writableHighWaterMark, process.stdin.readableHighWaterMark);
console.log('columns', typeof process.stdout.columns, typeof process.stdout.getWindowSize);
const r = process.stdout.write('cb-test\n', () => console.log('write callback called'));
console.log('write returned', r);
process.stderr.write('to stderr\n');
